type MailboxAddress = {
  name?: string;
  address: string;
};

type Thread = {
  id: string;
  messageIds: readonly string[];
  labelIds: readonly string[];
  subject: string;
  snippet: string;
  participants: readonly MailboxAddress[];
  lastMessageAt: string;
  unreadMessageCount: number;
  revision: string;
};

type Message = {
  readonly id: string;
  readonly threadId: string;
  readonly labelIds: readonly string[];
  readonly from: MailboxAddress;
  readonly to: readonly MailboxAddress[];
  readonly sentAt: string;
  readonly subject: string;
  readonly snippet: string;
  readonly bodyResourceId: string;
  readonly attachmentIds: readonly string[];
  readonly revision: string;
  readonly clientCommandId?: string;
};

type Label = {
  id: string;
  name: string;
  kind: 'system' | 'user';
  color?: string;
  revision: string;
};

type MailboxSnapshot = {
  mailboxId: string;
  syncCursor: string;
  threads: readonly Thread[];
  messages: readonly Message[];
  labels: readonly Label[];
  capturedAt: string;
};

type DraftContent = {
  to: readonly MailboxAddress[];
  cc: readonly MailboxAddress[];
  bcc: readonly MailboxAddress[];
  subject: string;
  bodyHtml: string;
  attachmentIds: readonly string[];
};

type DraftDocument = {
  draftId: string;
  mailboxId: string;
  threadId?: string;
  content: DraftContent;
  contentRevision: number;
  baseRemoteRevision: string | null;
  remoteRevision?: string;
  updatedAt: string;
};

type CommandBase = {
  commandId: string;
  idempotencyKey: string;
  baseRevision: string | null;
  createdAt: string;
};

type OutboxCommand =
  | (CommandBase & {
      kind: 'draft.save';
      draftId: string;
      document: DraftDocument;
    })
  | (CommandBase & {
      kind: 'draft.send';
      draftId: string;
      expectedContentRevision: number;
    })
  | (CommandBase & {
      kind: 'thread.labels.set';
      threadId: string;
      addLabelIds: readonly string[];
      removeLabelIds: readonly string[];
    });

type PendingCommand = {
  command: OutboxCommand;
  status: 'queued' | 'submitting' | 'awaiting-delta' | 'conflict' | 'failed';
  attemptCount: number;
  retryAfter?: string;
  lastErrorCode?: string;
};

type MailboxClientState = {
  mailbox: {
    threadsById: Record<string, Thread>;
    messagesById: Record<string, Message>;
    labelsById: Record<string, Label>;
    syncCursor: string | null;
    phase: 'empty' | 'cached' | 'syncing' | 'fresh' | 'stale' | 'recovering';
  };
  localIntent: {
    draftsById: Record<string, DraftDocument>;
    commandsById: Record<string, PendingCommand>;
  };
  view: {
    selectedThreadId?: string;
    activeLabelId?: string;
    query: string;
  };
  resources: {
    bodyCacheKeys: readonly string[];
    attachmentCacheKeys: readonly string[];
    localSearchVersion?: string;
  };
};
